# ---- SHAPES: a part is { c: control points, per, closed } or { pts }, its `fill` a tint (or attr, skin: what the bearer says), `paint` its lines --------
def C(pts, fill, per=3, closed=True, **k): return {"c": pts, "per": per, "closed": closed, "fill": fill, **k}
def Pg(pts, fill, **k): return {"pts": pts, "fill": fill, **k}
def Ln(pts, w=.5, **k): return {"pts": pts, "w": w, **k}
def Cv(pts, w=.5, per=3, **k): return {"c": pts, "per": per, "w": w, **k}
def bar(x0, y0, x1, y1, w, fill, **k):
    d = math.hypot(x1 - x0, y1 - y0) or 1; nx, ny = -(y1 - y0) / d * w, (x1 - x0) / d * w
    return Pg([[x0 - nx, y0 - ny], [x1 - nx, y1 - ny], [x1 + nx, y1 + ny], [x0 + nx, y0 + ny]], fill, **k)
def rect(x0, y0, x1, y1, fill, **k): return Pg([[x0, y0], [x1, y0], [x1, y1], [x0, y1]], fill, **k)
def disc(x, y, r, fill, n=14, **k): return Pg([[round(x + r * math.cos(i * math.tau / n), 2), round(y + r * math.sin(i * math.tau / n), 2)] for i in range(n)], fill, **k)
def ringline(x, y, r, n=14, w=.5, **k): return Ln([[round(x + r * math.cos(i * math.tau / n), 2), round(y + r * math.sin(i * math.tau / n), 2)] for i in range(n)], w, closed=True, **k)

