# THINGS THAT STAND IN A SCENE: anchors, parts. x centred, y up from the ground; `span` stretches over the frame (base: along the foot; top: hung from the head)
def _stone(x0, y0, x1, y1, n, m):
    out = []
    for j in range(1, m): out.append(Ln([[x0, y0 + (y1 - y0) * j / m], [x1, y0 + (y1 - y0) * j / m]], .3, alpha=.7))
    return out
def _towers(xs, h, w, fill="grey", roof="ruby"): return [p for x, k in xs for p in (rect(x - w, 0, x + w, h * k, fill, paint=[Ln([[x - w, h * k * .9], [x + w, h * k * .9]], .5), Cv([[x - w * .4, h * k * .5], [x, h * k * .6], [x + w * .4, h * k * .5]], .4), Ln([[x, h * k * .45], [x, h * k * .58]], .4)]), Pg([[x - w * 1.3, h * k], [x + w * 1.3, h * k], [x, h * k + w * 2.2]], roof))]
_wave = lambda y, n=8, a=2.6: Cv([[-1 + 2 * i / n, y + (a if i % 2 else -a)] for i in range(n + 1)], .7, closed=False)
