# BEASTS, drawn for the frontal age (no rig: they stand in scenes as things, saddled at `seat`, led by `mouth`). Facing +x, feet at 0; a gait is another drawing
def leg(x0, y0, kx, ky, fx, fy, w, fill, hoof=None, **k):
    a = bar(x0, y0, kx, ky, w, fill, role="beast", **k); b = bar(kx, ky, fx, fy, w * .72, fill, role="beast", **k)
    return [a, b] + ([rect(fx - w * .85, fy - .4, fx + w * 1.1, fy + w * 1.1, hoof, role="beast")] if hoof else [])
_eye = lambda x, y, r=1.2: {"pts": [[x - r, y], [x + r, y], [x, y + r * 1.1]], "ink": "#1d120b"}
def horse(legs, fill="white"):
    body = C([[-36, 46], [-38, 60], [-26, 68], [-4, 65], [12, 68], [26, 77], [36, 91], [44, 100], [50, 100], [63, 88], [65, 81], [58, 79], [50, 84], [44, 76], [39, 60], [30, 47], [14, 41], [-14, 41]], fill, per=2, role="beast", paint=[_eye(50, 91), Cv([[28, 74], [38, 90], [44, 98]], .9), Cv([[-26, 62], [-8, 58], [14, 60]], .4), Cv([[-30, 46], [-8, 43], [20, 46]], .4), Ln([[58, 79], [65, 84]], .5)])
    tail = C([[-36, 62], [-46, 58], [-52, 32], [-44, 30], [-38, 48]], "brown", per=2, role="beast")
    return {"parts": [tail] + [p for q in legs for p in leg(*q[:7], fill, "navy")] + [body, C([[29, 76], [36, 91], [42, 101], [47, 102], [41, 88], [37, 72]], "brown", per=2, role="beast")], "anchors": {"seat": [-2, 67], "mouth": [62, 84]}}
